type AdditionalMessageKey = keyof typeof additionalMessages;
const additionalEn = Object.fromEntries(Object.entries(additionalMessages).map(([key, value]) => [key, value.en])) as Record<AdditionalMessageKey, string>;
const additionalKk = Object.fromEntries(Object.entries(additionalMessages).map(([key, value]) => [key, value.kk])) as Record<AdditionalMessageKey, string>;
const completeEn = { ...en, ...supplementalEn, ...additionalEn };
const completeKk: Record<keyof typeof completeEn, string> = { ...kk, ...supplementalKk, ...additionalKk };

export const interfaceDictionaries = { en: completeEn, kk: completeKk } as const;
const dictionaries = interfaceDictionaries;
export type InterfaceMessageKey = keyof typeof completeEn;
export const supportedInterfaceLanguages: readonly Language[] = ["ru", "en", "kk"];

export function translateMessage(key: InterfaceMessageKey, language: Language): string {
  return language === "ru" ? key : dictionaries[language][key];
}
const originalText = new WeakMap<Text, string>();
const originalAttributes = new WeakMap<Element, Map<string, string>>();

function translateValue(value: string, language: Language) {
  if (language === "ru") return value;
  const match = value.match(/^(\s*)([\s\S]*?)(\s*)$/);
  if (!match) return value;
  const source = match[2];
  const dictionary = dictionaries[language] as Record<string, string>;
  let translated = dictionary[source];
  if (!translated) {
    const greeting = source.match(/^Добрый день,\s*(.+)!$/);
    const completed = source.match(/^Пройдено\s*(.+)$/);
    const minutes = source.match(/^(\d+(?:[.,]\d+)?)\s+минут(?:ы)?$/);
    const countOf = source.match(/^(\d+)\s+из\s+(\d+)$/);
    const activitiesFor = source.match(/^Занятия\s+(.+)$/);
    const supporting = source.match(/^Вместе поддерживаем\s+(.+)$/);
    const age = source.match(/^(.+),\s*(\d+)\s+лет$/);
    const averageAttempts = source.match(/^среднее по\s+(\d+)\s+игровым попыткам$/);
    const attempts = source.match(/^(\d+)\s+игровых попыток$/);
    const todayActivities = source.match(/^(\d+)\s+заданий сегодня$/);
    const weekActivities = source.match(/^(\d+)\s+заданий за неделю$/);
    const practiceDays = source.match(/^(\d+)\s+дней практики$/);
    const weekPractice = source.match(/^(\d+(?:[.,]\d+)?)\s+мин практики за неделю$/);
    const gameScore = source.match(/^(\d+)%\s+в игре$/);
    const recommended = source.match(/^Для следующей практики:\s*(.+)$/);
    const labelledValue = source.match(/^([^:]+):\s*(.+)$/);
    if (greeting) translated = language === "en" ? `Good afternoon, ${greeting[1]}!` : `Қайырлы күн, ${greeting[1]}!`;
    else if (completed) translated = language === "en" ? `Completed ${completed[1]}` : `Орындалды ${completed[1]}`;
    else if (minutes) translated = language === "en" ? `${minutes[1]} minutes` : `${minutes[1]} минут`;
    else if (countOf) translated = language === "en" ? `${countOf[1]} of ${countOf[2]}` : `${countOf[2]}-дан ${countOf[1]}`;
    else if (activitiesFor) translated = language === "en" ? `Activities for ${activitiesFor[1]}` : `${activitiesFor[1]} сабақтары`;
    else if (supporting) translated = language === "en" ? `Supporting ${supporting[1]} together` : `${supporting[1]} бірге қолдаймыз`;
    else if (age) translated = language === "en" ? `${age[1]}, age ${age[2]}` : `${age[1]}, ${age[2]} жаста`;
    else if (averageAttempts) translated = language === "en" ? `average across ${averageAttempts[1]} activity attempts` : `${averageAttempts[1]} ойын талпынысының орташа мәні`;
    else if (attempts) translated = language === "en" ? `${attempts[1]} activity attempts` : `${attempts[1]} ойын талпынысы`;
    else if (todayActivities) translated = language === "en" ? `${todayActivities[1]} activities today` : `бүгін ${todayActivities[1]} тапсырма`;
    else if (weekActivities) translated = language === "en" ? `${weekActivities[1]} activities this week` : `осы аптада ${weekActivities[1]} тапсырма`;
    else if (practiceDays) translated = language === "en" ? `${practiceDays[1]} practice days` : `${practiceDays[1]} жаттығу күні`;
    else if (weekPractice) translated = language === "en" ? `${weekPractice[1]} min of practice this week` : `осы аптада ${weekPractice[1]} мин жаттығу`;
    else if (gameScore) translated = language === "en" ? `${gameScore[1]}% in the activity` : `ойында ${gameScore[1]}%`;
    else if (recommended) {
      const [skill, practice] = recommended[1].split(" — ");
      const translatedSkill = dictionary[skill] || skill;
      const translatedPractice = practice ? dictionary[practice.replace(/\.$/, "")] || practice.replace(/\.$/, "") : "";
      translated = language === "en" ? `For the next practice: ${translatedSkill}${translatedPractice ? ` — ${translatedPractice.toLowerCase()}.` : ""}` : `Келесі жаттығуға: ${translatedSkill}${translatedPractice ? ` — ${translatedPractice.toLowerCase()}.` : ""}`;
    } else if (labelledValue && dictionary[labelledValue[1]] && (dictionary[labelledValue[2].replace(/\.$/, "")] || dictionary[labelledValue[2].replace(/\.$/, "").charAt(0).toUpperCase() + labelledValue[2].replace(/\.$/, "").slice(1)])) {
      const label = dictionary[labelledValue[1]] || labelledValue[1];
      const rawDetail = labelledValue[2].replace(/\.$/, "");
      const detail = dictionary[rawDetail] || dictionary[rawDetail.charAt(0).toUpperCase() + rawDetail.slice(1)] || rawDetail;
      translated = `${label}: ${detail}${labelledValue[2].endsWith(".") ? "." : ""}`;
    } else {
      const translatedMonths = language === "en"
        ? source.replace(/янв\./g, "Jan").replace(/февр\./g, "Feb").replace(/марта/g, "Mar").replace(/апр\./g, "Apr").replace(/мая/g, "May").replace(/июня/g, "Jun").replace(/июля/g, "Jul").replace(/авг\./g, "Aug").replace(/сент\./g, "Sep").replace(/окт\./g, "Oct").replace(/нояб\./g, "Nov").replace(/дек\./g, "Dec")
        : source.replace(/янв\./g, "қаң.").replace(/февр\./g, "ақп.").replace(/марта/g, "нау.").replace(/апр\./g, "сәу.").replace(/мая/g, "мам.").replace(/июня/g, "мау.").replace(/июля/g, "шіл.").replace(/авг\./g, "там.").replace(/сент\./g, "қыр.").replace(/окт\./g, "қаз.").replace(/нояб\./g, "қар.").replace(/дек\./g, "жел.");
      if (translatedMonths !== source) translated = translatedMonths;
    }
  }
  return `${match[1]}${translated || source}${match[3]}`;
}

function translateTree(root: ParentNode, language: Language) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node = walker.nextNode() as Text | null;
  while (node) {
    if (node.parentElement?.closest("[data-i18n-native]")) { node = walker.nextNode() as Text | null; continue; }
    if (!originalText.has(node)) originalText.set(node, node.nodeValue || "");
    const next = translateValue(originalText.get(node) || "", language);
    if (node.nodeValue !== next) node.nodeValue = next;
    node = walker.nextNode() as Text | null;
  }
  const elements = root instanceof Element ? [root, ...root.querySelectorAll("*")] : [...root.querySelectorAll("*")];
  for (const element of elements) for (const name of ["placeholder", "aria-label", "title"]) {
    if (element.closest("[data-i18n-native]")) continue;
    if (!element.hasAttribute(name)) continue;
    let saved = originalAttributes.get(element);
    if (!saved) { saved = new Map(); originalAttributes.set(element, saved); }
    if (!saved.has(name)) saved.set(name, element.getAttribute(name) || "");
    element.setAttribute(name, translateValue(saved.get(name) || "", language));
  }
}

export function useInterfaceLanguage(language: Language) {
  useEffect(() => {
    let active = true;
    document.documentElement.lang = language === "kk" ? "kk" : language;
    document.title = language === "en" ? "Söyle — learn, communicate, grow" : language === "kk" ? "Söyle — үйренеміз, сөйлесеміз, өсеміз" : "Söyle — играем, общаемся, растём";
    localStorage.setItem("soyle-language", language);
    translateTree(document.body, language);
    const observer = new MutationObserver((items) => {
      if (!active) return;
      for (const item of items) {
        if (item.type === "characterData" && item.target instanceof Text) {
          const current = item.target.nodeValue || "";
          const translated = translateValue(current, language);
          if (translated !== current) {
            originalText.set(item.target, current);
            item.target.nodeValue = translated;
          }
        }
        for (const node of item.addedNodes) {
          if (node instanceof Text) {
            if (!originalText.has(node)) originalText.set(node, node.nodeValue || "");
            node.nodeValue = translateValue(originalText.get(node) || "", language);
          } else if (node instanceof Element) translateTree(node, language);
        }
      }
    });
    observer.observe(document.body, { childList: true, characterData: true, subtree: true });
    return () => { active = false; observer.disconnect(); };
  }, [language]);
}
